module pulse_detect #(
    parameter s0 = 2'b00,
    parameter s1 = 2'b01,
    parameter s2 = 2'b10,
    parameter s3 = 2'b11
) (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    parameter IDLE = 2'b00;
    parameter RISING = 2'b01;
    parameter FALLING = 2'b10;
    parameter PULSE_END = 2'b11;

    reg [1:0] state;

    reg [1:0] next_state;

    always @(*) begin
        case (state)
            IDLE: begin
                if (data_in == 1'b0) next_state = RISING;
                else next_state = IDLE;
            end
            RISING: begin
                if (data_in == 1'b1) next_state = FALLING;
                else next_state = IDLE;
            end
            FALLING: begin
                if (data_in == 1'b0) next_state = PULSE_END;
                else next_state = RISING;
            end
            PULSE_END: begin
                if (data_in == 1'b1) next_state = FALLING;
                else next_state = IDLE;
            end
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        data_out = (state == FALLING) && (data_in == 1'b0);
    end

endmodule
